    public void init()
    {
        next init();

        this.metInitCopyRecords();
    }

    /// <summary>
    /// CoC on Form Closed
    /// </summary>
    /// <returns>closed or not</returns>
    public boolean closed()
    {
        boolean ret;

        ret = next closed();

        if (metMarkupAutoTable.RecId)
        {
            ttsbegin;
            metMarkupAutoTable.selectForUpdate(true);
            metMarkupAutoTable.reread();
            metMarkupAutoTable.metLineUpdated = metMarkupAutoTable.metLineUpdated + 1 ;
            metMarkupAutoTable.update();
            ttscommit;
        }
        return ret;
    }

/// <summary>
/// Initilize a copy record
/// </summary>
public void metInitCopyRecords()
{
    metArgsRecord = this.args().record();
    
    if (metArgsRecord is MarkupAutoLine)
    {
        metMarkupAutoLine = metArgsRecord;
        metMarkupAutoTable = metMarkupAutoLine.metMarkupTable();
    }
    else if (metArgsRecord is MarkupAutoTable)
    {
        metMarkupAutoTable = metArgsRecord;
    }
}
